rest.assertionCode:
def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or not isinstance(responseBody, dict) or responseBody.get("code") != 0:
        raise Blocked("社区准备请求失败")
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) < 2 or not data[0].get("id") or not data[1].get("id") or data[0]["id"] == data[1]["id"]:
        raise Blocked("需要两个不同社区；公开 HTTP 无社区创建接口")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("读取注册用户初始社区时间失败")
    assert responseBody["data"]["id"] == globalParam["USER_A"]
    assert responseBody["data"]["communityId"] == globalParam["COMMUNITY_A"]
    changed = responseBody["data"].get("communityChangedAt")
    if not isinstance(changed, str) or not changed:
        raise Blocked("communityChangedAt 为空或非字符串")
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if statusCode != 200 or responseBody.get("code") != 0:
        raise Blocked("七天自然等待后刷新失败，不能继续使用过期访问令牌；仍需清理账号")
    assert responseBody["data"]["user"]["id"] == globalParam["USER_A"]
    assert responseBody["data"]["accessToken"] and responseBody["data"]["refreshToken"]
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    assert statusCode == 409 and responseBody["code"] == 40901
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    assert responseBody.get("requestId")
    if statusCode == 200 and responseBody["code"] == 0:
        assert responseBody["data"]["id"] == globalParam["USER_A"]
        return True
    return statusCode == 401 and responseBody["code"] == 40101

def assert_response(responseBody, globalParam, statusCode, headers):
    assert statusCode == 200 and responseBody["code"] == 0
    assert responseBody.get("requestId")
    return responseBody["data"] == {}
